import type { GamesApi } from "../../api";
import { makeFindTheShiny, type ShinyDiff } from "./logic";
import { makeView } from "./view";
// generated by measure.ts; text, so it is parsed as JSON rather than as code
import raw from "./shiny-diff.json" with { type: "text" };

/** Find the shiny: one pokémon in the grid is shiny; pick it. */
export default function pack(games: GamesApi): void {
  const diff = (JSON.parse(raw as unknown as string) as { diff: ShinyDiff }).diff;
  const dataset = () => games.registry.getDataset("pokemon");
  const def = makeFindTheShiny(dataset, diff);
  games.registry.puzzle(def);
  games.registry.view(makeView(dataset, def));
}
